// Database Actions
const CREATE = "CREATE"; // create a booking
const FETCH = "FETCH"; // get a single booking
const DELETE = "DELETE"; // deletes a single booking
const FETCH_ALL = "FETCH_ALL"; // get all bookings, admin only
const AUTH = "AUTH"; // handle admin auth
const LOGOUT = "LOGOUT"; // logs admin out
const FETCH_ROOMS = "FETCH_ROOMS"; // grabs all rooms, for Rooms component, read only
const ROOM = "ROOM"; // grabs specified room, for Room Component
const AVAILABLE = "AVAILABLE"; // shows all available rooms

// Booking details action
const ROOM_DET = "ROOM_DET";
const INFO_DET = "INFO_DET";
const BOOK_DET = "BOOK_DET";

// Local state management
const PRICE = "PRICE";
const TOTAL = "TOTAL";

// Server status
const AWAKE = "AWAKE";

// Exporting the constants
module.exports = {
  CREATE,
  FETCH,
  DELETE,
  FETCH_ALL,
  AUTH,
  LOGOUT,
  FETCH_ROOMS,
  ROOM,
  AVAILABLE,
  ROOM_DET,
  INFO_DET,
  BOOK_DET,
  PRICE,
  TOTAL,
  AWAKE,
};
